const bedUpgrades=[{id:'wood',name:'Деревянные бортики',kind:'inspect',price:4000,icon:'🪵',description:'Материалы и установка по периметру грядки до 3 м².'},{id:'concrete',name:'Бетонный бордюр',kind:'inspect',price:12000,icon:'🧱',description:'Подготовка основания, материалы и устройство бордюра до 3 м².'},{id:'drip',name:'Автополив',kind:'drip',price:5500,icon:'💧',description:'Капельная линия, фильтр, таймер и монтаж до 3 м². Источник воды согласуется.'},{id:'trellis',name:'Шпалера',kind:'trellis',price:2500,icon:'🌿',description:'Опоры, сетка и установка до 3 м².'},{id:'cover',name:'Укрытие грядки',kind:'cover',price:3500,icon:'🏡',description:'Дуги, укрывной материал и монтаж до 3 м².'}];
function upgradePrice(u,p){return Math.round(u.price*Math.max(1,Number(p?.size||3)/3))}
function upgradeCards(plot){return `<section class="panel"><h2>Улучшения из маркета</h2><p>Предварительные демо-цены с монтажом. Ферма подтвердит совместимость, стоимость и срок до выполнения.</p><div class="room-actions">${bedUpgrades.map(u=>roomTile(u.icon,u.name,u.description,`orderBedUpgrade('${u.id}',${plot?.id||'null'})`,`${plot?'':'От '}${upgradePrice(u,plot)} демо-₽`)).join('')}</div></section>`}
function orderBedUpgrade(id,plot){if(!account)return profile();if(!myPlots().length){toast('Сначала арендуйте грядку');return}const u=bedUpgrades.find(u=>u.id===id);if(!u)return;const chosen=myPlots().find(p=>p.id===plot)||myPlots()[0];formAsync(u.name,`<label>Грядка<select name="plot" onchange="updateUpgradeQuote('${id}',this.value)">${myPlots().map(p=>`<option value="${p.id}" ${p.id===chosen.id?'selected':''}>${esc(p.name)} · ${p.size} м²</option>`).join('')}</select></label><h3 id="upgrade-quote">${upgradePrice(u,chosen)} демо-₽ · предварительно</h3><p>${u.description}</p><label>Пожелания<textarea name="notes" maxlength="400"></textarea></label><p>Создаётся одна заявка на согласование. Деньги сейчас не списываются. Сотрудник уточнит смету и время работ.</p><button class="btn">Отправить заявку на установку</button>`,async f=>{const p=myPlots().find(p=>p.id===Number(f.get('plot')));if(!p)throw Error('Выберите свою грядку');await api('life-request',{plot:p.id,kind:u.kind,details:`[Улучшение: ${u.id}] ${u.name}. Площадь ${p.size} м². Предварительная демо-смета ${upgradePrice(u,p)} ₽, материалы и монтаж. Требует согласования. ${f.get('notes')||''}`});await loadLife();openFarmBed(p.id,'activity');toast('Заявка отправлена и видна в ходе работ')})}
function updateUpgradeQuote(id,plot){const u=bedUpgrades.find(x=>x.id===id),p=myPlots().find(x=>x.id===Number(plot));document.getElementById('upgrade-quote').textContent=upgradePrice(u,p)+' демо-₽ · предварительно'}
const marketBeforeUpgrades=demoMarketPage;demoMarketPage=function(){return upgradeCards()+marketBeforeUpgrades()};
const renderBeforeUpgrades=render;render=function(){renderBeforeUpgrades();const p=currentRoomPlot();if(p&&plotRoomTab==='build')document.querySelector('[role=tabpanel]')?.insertAdjacentHTML('afterbegin',upgradeCards(p));if(p&&['activity','build'].includes(plotRoomTab)){const requests=(lifeData?.requests||[]).filter(r=>r.plot_id===p.id);if(requests.length)document.querySelector('[role=tabpanel]')?.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Установка и улучшения</h2>${requests.map(r=>`<article class="event"><b>${esc(lifeKinds[r.kind]||'Улучшение')}</b><p>${esc(r.details)}</p><span class="pill">${esc(lifeStatus[r.status]||r.status)}</span><p>${esc(r.report||'Ожидает согласования фермы')}</p>${account.role==='admin'?`<button class="btn light" onclick="reviewLifeRequest('${r.id}')">Обновить статус</button>`:''}</article>`).join('')}</section>`)}};
addEventListener('hashchange',()=>{if(account&&(currentRoomPlot()||location.hash==='#market'))loadLife()});if(account)loadLife();render();
